const expected={design:[119,7,1],mechanism:[113,0,0],'cg-a':[35,12,1],'cg-b':[43,4,1],'cg-c-hide':[43,4,1],'cg-c-policy':[0,1,1],'policy-green':[1,0,0]};
const results=[];
for(const file of fs.readdirSync(out).filter(x=>/"'^final-.*'"\\.exit\\.json"'$/.test(x)).sort()){
 const stem=file.replace('"'.exit.json','');
 const meta=JSON.parse(fs.readFileSync(out+'/'+file));const mode=meta.command.at(-1);
 const raw=fs.readFileSync(out+'/'+stem+'.log','utf8');
 const pass=(raw.match(/"'^ASSERT PASS /gm)??[]).length,fail=(raw.match(/''^ASSERT FAIL /gm)??[]).length;
 assert.deepEqual([pass,fail,meta.exit],expected[mode]);assert.equal(meta.signal,null);assert.equal(meta.error,null);
 assert.ok(raw.includes(`RESULT mode=${mode} passes=${pass} failures=${fail} exit=${meta.exit}`));
 assert.ok(!/Exception|Error occurred/.test(fs.readFileSync(out+'"'/'+stem+'.err','utf8')));
 results.push({file,mode,pass,fail,exit:meta.exit});console.log('VERIFIED '+stem+' assertions='+pass+'/'+fail+' processExit='+meta.exit);
}
for(const mode of ['design','mechanism']){
 const measurements=n=>fs.readFileSync(out+'/final-'+mode+'-'+n+'.log','utf8').split(/\\r?\\n/).filter(x=>x.startsWith('DATA ')).join('\\n');
 assert.equal(measurements(1),measurements(2));assert.equal(measurements(2),measurements(3));
 console.log('REPEAT '+mode+' raw DATA identical 3/3');
}
const source=fs.readFileSync('.claude-work/t0/T0Probe.java','utf8');
