assert.ok("'!/com'"\\.mhtextractor|java\\.lang\\.reflect|setAccessible|getDeclaredField|getDeclaredMethod/.test(source));
console.log('SOURCE imports='+imports.length+' all javafx; product references=0; reflection=0');
const before=JSON.parse(fs.readFileSync(out+'/repo-before.json'));
const changed=before.filter(({p,hash})=>(fs.existsSync(p)?crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex'):null)"'!==hash);
fs.writeFileSync(out+'"'/repo-audit.json',JSON.stringify({tracked:before.length,changed},null,2));assert.equal(changed.length,0);
console.log('REPO tracked='+before.length+' contentChanged='+changed.length);
const after=snapshot();fs.writeFileSync(out+'/c-after.json',JSON.stringify(after,null,2));
const cAudit=compare(JSON.parse(fs.readFileSync(out+'/c-before.json')),after);fs.writeFileSync(out+'/c-audit.json',JSON.stringify(cAudit,null,2));
console.log('C-AUDIT projectStatus='+cAudit.projectStatus+' projectAdded='+cAudit.counts.project+' projectModified='+cAudit.modifiedCounts.project+' unreadable='+cAudit.unreadable.length+' counts='+JSON.stringify(cAudit.counts));assert.equal(cAudit.projectStatus,'PASS');
const files=fs.readdirSync('.claude-work/t0');console.log('LOCAL_FILES '+files.join(', '));
fs.writeFileSync(out+'/verification.json',JSON.stringify({results,tracked:before.length,changed:changed.length,sourceHash:crypto.createHash('sha256').update(source).digest('hex'),cProjectStatus:cAudit.projectStatus,cAdded:cAudit.counts,cModified:cAudit.modifiedCounts,files},null,2));
console.log(cp.execFileSync('git',['status','--short'],{encoding:'utf8'}));
